"use strict"

/* Tracker link: everything on the scenario pages that is a number, an event, a country or a source
   comes from tracker-data.js, generated by pipeline/tracker.py from the Sector Research Tracker.
   This file adds no figures of its own except approximate country centres. */

/* ISO3 → [name, latitude, longitude, UN M49 subregion used by the scenario model]. Centres are approximate. */
var TRK_GEO = {"USA":["United States",39.8,-98.6,"northamerica"],"CAN":["Canada",56.1,-106.3,"northamerica"],"MEX":["Mexico",23.6,-102.6,"central-america"],"BRA":["Brazil",-10.8,-52.9,"south-america"],"ARG":["Argentina",-34.0,-64.0,"south-america"],"CHL":["Chile",-33.5,-70.7,"south-america"],"COL":["Colombia",4.6,-74.1,"south-america"],"PER":["Peru",-9.2,-75.0,"south-america"],"BOL":["Bolivia",-16.3,-63.6,"south-america"],"CRI":["Costa Rica",9.7,-83.8,"central-america"],"GBR":["United Kingdom",54.0,-2.0,"north-europe"],"IRL":["Ireland",53.4,-8.2,"north-europe"],"DEU":["Germany",51.2,10.4,"west-europe"],"FRA":["France",46.6,2.2,"west-europe"],"NLD":["Netherlands",52.1,5.3,"west-europe"],"BEL":["Belgium",50.5,4.5,"west-europe"],"LUX":["Luxembourg",49.8,6.1,"west-europe"],"CHE":["Switzerland",46.8,8.2,"west-europe"],"AUT":["Austria",47.5,14.6,"west-europe"],"ITA":["Italy",42.8,12.6,"south-europe"],"ESP":["Spain",40.2,-3.6,"south-europe"],"PRT":["Portugal",39.6,-8.0,"south-europe"],"GRC":["Greece",39.1,22.0,"south-europe"],"SVN":["Slovenia",46.1,14.8,"south-europe"],"HRV":["Croatia",45.1,15.2,"south-europe"],"SWE":["Sweden",62.0,15.0,"north-europe"],"NOR":["Norway",61.0,9.0,"north-europe"],"FIN":["Finland",64.0,26.0,"north-europe"],"DNK":["Denmark",56.0,10.0,"north-europe"],"ISL":["Iceland",64.9,-18.6,"north-europe"],"EST":["Estonia",58.6,25.0,"north-europe"],"LVA":["Latvia",56.9,24.6,"north-europe"],"LTU":["Lithuania",55.2,23.9,"north-europe"],"POL":["Poland",52.1,19.4,"east-europe"],"CZE":["Czechia",49.8,15.5,"east-europe"],"SVK":["Slovak Republic",48.7,19.7,"east-europe"],"HUN":["Hungary",47.2,19.5,"east-europe"],"ROU":["Romania",45.9,24.9,"east-europe"],"BGR":["Bulgaria",42.7,25.5,"east-europe"],"UKR":["Ukraine",49.0,31.4,"east-europe"],"RUS":["Russia",61.5,98.0,"east-europe"],"TUR":["Türkiye",39.0,35.2,"west-asia"],"ISR":["Israel",31.4,35.0,"west-asia"],"SAU":["Saudi Arabia",23.9,45.1,"west-asia"],"ARE":["United Arab Emirates",23.4,53.8,"west-asia"],"QAT":["Qatar",25.3,51.2,"west-asia"],"BHR":["Bahrain",26.0,50.6,"west-asia"],"IRN":["Iran",32.4,53.7,"south-asia"],"ARM":["Armenia",40.1,45.0,"west-asia"],"EGY":["Egypt",26.8,30.8,"north-africa"],"MAR":["Morocco",31.8,-7.1,"north-africa"],"ZAF":["South Africa",-30.6,22.9,"southern-africa"],"NGA":["Nigeria",9.1,8.7,"west-africa"],"GHA":["Ghana",7.9,-1.0,"west-africa"],"CIV":["Côte d'Ivoire",7.5,-5.5,"west-africa"],"SEN":["Senegal",14.5,-14.5,"west-africa"],"SLE":["Sierra Leone",8.5,-11.8,"west-africa"],"KEN":["Kenya",0.0,37.9,"east-africa"],"ETH":["Ethiopia",9.1,40.5,"east-africa"],"RWA":["Rwanda",-1.9,29.9,"east-africa"],"MDG":["Madagascar",-18.8,46.9,"east-africa"],"MOZ":["Mozambique",-18.7,35.5,"east-africa"],"ZWE":["Zimbabwe",-19.0,29.2,"east-africa"],"COD":["DR Congo",-2.9,23.7,"central-africa"],"GAB":["Gabon",-0.8,11.6,"central-africa"],"KAZ":["Kazakhstan",48.0,67.0,"central-asia"],"MNG":["Mongolia",46.9,103.8,"east-asia"],"CHN":["China",35.9,104.2,"east-asia"],"HKG":["Hong Kong SAR, China",22.3,114.2,"east-asia"],"JPN":["Japan",36.2,138.3,"east-asia"],"KOR":["Korea, Rep.",36.5,127.9,"east-asia"],"PRK":["North Korea",40.3,127.5,"east-asia"],"IND":["India",21.0,78.0,"south-asia"],"PAK":["Pakistan",30.4,69.3,"south-asia"],"BGD":["Bangladesh",23.7,90.4,"south-asia"],"SGP":["Singapore",1.35,103.8,"southeast-asia"],"MYS":["Malaysia",4.2,102.0,"southeast-asia"],"THA":["Thailand",15.9,101.0,"southeast-asia"],"IDN":["Indonesia",-2.5,118.0,"southeast-asia"],"VNM":["Viet Nam",16.0,107.8,"southeast-asia"],"PHL":["Philippines",12.9,121.8,"southeast-asia"],"AUS":["Australia",-25.3,133.8,"australia-new-zealand"],"NZL":["New Zealand",-41.0,174.0,"australia-new-zealand"],"NCL":["New Caledonia",-21.3,165.6,"melanesia"]}
var TRK_ALIAS = {"DR Congo":"COD","Turkey":"TUR","Türkiye":"TUR","Turkiye":"TUR","Vietnam":"VNM","Viet Nam":"VNM","Korea, Rep.":"KOR","Slovak Republic":"SVK","Côte d'Ivoire":"CIV","Hong Kong SAR, China":"HKG"}

/* Percent change of a 2035 input that equals the full model range (±2) of an industry or metal driver. */
var TRK_FULL_RANGE_PCT = 50
var TRK_LEVEL_PER_PCT = 2 / TRK_FULL_RANGE_PCT


function trkReady() { return typeof TRACKER === "object" && TRACKER !== null }

function trkIso(name) {
  if (!name) return ""
  if (TRK_ALIAS[name]) return TRK_ALIAS[name]
  var hit = Object.keys(TRK_GEO).find(function (iso) { return TRK_GEO[iso][0] === name })
  return hit || ""
}

function trkFmt(value, unit) {
  if (value == null || !Number.isFinite(value)) return "—"
  var abs = Math.abs(value)
  var text = abs >= 1e9 ? (value / 1e9).toFixed(1) + " bn" : abs >= 1e6 ? (value / 1e6).toFixed(1) + " m" :
    abs >= 100 ? Math.round(value).toLocaleString("en-US") : abs >= 10 ? value.toFixed(1) : value.toFixed(2)
  return text + (unit ? " " + unit : "")
}

function trkPctText(pct) {
  var r = Math.round(pct)
  return (r > 0 ? "+" : r < 0 ? "−" : "±") + Math.abs(r) + "%"
}

/* ---------- Sources ---------- */

function trkSourceLink(id) {
  var s = trkReady() && TRACKER.sources[id]
  if (!s) return id ? '<span class="trk-src" title="Not in the tracker Source Log">' + esc(id) + "</span>" : ""
  var title = s.publisher + " · " + s.name + (s.year ? " (" + s.year + ")" : "") + (s.limits ? " — Limits: " + s.limits : "")
  return s.url ? '<a class="trk-src" href="' + esc(s.url) + '" target="_blank" rel="noopener" title="' + esc(title) + '">' + esc(id) + "</a>"
    : '<span class="trk-src" title="' + esc(title) + '">' + esc(id) + "</span>"
}

function trkSources(ids) {
  var list = (ids || []).filter(Boolean)
  return list.length ? list.map(trkSourceLink).join(" ") : '<span class="trk-src trk-missing">no Source ID</span>'
}

/* ---------- Countries ---------- */

function trkCountryOptions() {
  if (!trkReady()) return []
  var seen = {}
  TRACKER.countryData.countries.forEach(function (c) { seen[c.iso] = c.name })
  TRACKER.production.forEach(function (p) { var iso = trkIso(p.country); if (iso) seen[iso] = seen[iso] || TRK_GEO[iso][0] })
  return Object.keys(seen).filter(function (iso) { return TRK_GEO[iso] }).map(function (iso) {
    return { iso: iso, name: TRK_GEO[iso][0], group: (SCN_REGIONS[TRK_GEO[iso][3]] || {}).group || "Other" }
  }).sort(function (a, b) { return a.name.localeCompare(b.name) })
}

function trkCountry(params) {
  var iso = params && params.get("scn-country")
  return iso && TRK_GEO[iso] ? iso : ""
}

function trkCountrySelect(params) {
  var current = trkCountry(params)
  var groups = {}
  trkCountryOptions().forEach(function (c) { (groups[c.group] = groups[c.group] || []).push(c) })
  return '<label for="scn-country">Country</label><select id="scn-country" name="scn-country" data-control>' +
    '<option value="">Global (all countries)</option>' +
    Object.keys(groups).sort().map(function (g) {
      return '<optgroup label="' + esc(g) + '">' + groups[g].map(function (c) {
        return '<option value="' + c.iso + '"' + (c.iso === current ? " selected" : "") + ">" + esc(c.name) + "</option>"
      }).join("") + "</optgroup>"
    }).join("") + "</select>"
}

/* ---------- 2035 events ---------- */

function trkEvents(key) {
  if (!trkReady()) return []
  return TRACKER.events.filter(function (e) { return !key || e.sector === key })
}

function trkEventValue(params, e) {
  var v = Number(params && params.get("ev-" + e.id))
  return Number.isFinite(v) && v > 0 ? v : e.target.value
}

function trkEventPct(params, e) { return (trkEventValue(params, e) / e.target.value - 1) * 100 }

/* Sum of event inputs for one model industry, in driver levels (±2 = ±50% vs the tracker 2035 value). */
function trkEventLevel(params, industryKey) {
  var level = 0
  trkEvents().forEach(function (e) {
    if (e.key === industryKey && params && params.get("ev-" + e.id)) level += trkEventPct(params, e) * TRK_LEVEL_PER_PCT
  })
  return Math.max(-2, Math.min(2, level))
}

function trkActiveEvents(params) {
  return trkEvents().filter(function (e) { return params && params.get("ev-" + e.id) && Math.abs(trkEventPct(params, e)) >= 0.5 })
}

function trkEventIndustry(params) {
  var sector = params && params.get("scn-ev-industry")
  return trkReady() && TRACKER.sectors[sector] ? sector : ""
}

function trkEventCard(params, e) {
  var value = trkEventValue(params, e)
  var pct = trkEventPct(params, e)
  var step = Math.max(e.target.value / 100, 0.01)
  var cagr = Math.pow(e.target.value / e.base.value, 1 / (2035 - e.base.year)) - 1
  var linked = e.linked.map(function (l) {
    var now = l.value * value / e.target.value
    return '<li>' + esc(l.label) + ": " + trkFmt(l.value, l.unit) + " → <b>" + trkFmt(now, l.unit) + "</b> (" + trkSources(l.sources) + ", " + esc(l.type.toLowerCase()) + ")</li>"
  }).join("")
  return '<article class="trk-event">' +
    '<h4>' + esc(e.label) + ' <small>' + esc(e.region) + "</small></h4>" +
    '<p class="trk-baseline">' + e.base.year + ": " + trkFmt(e.base.value, e.unit) + " (" + esc(e.base.type) + ") → 2035 in tracker: <b>" +
    trkFmt(e.target.value, e.unit) + "</b> (" + esc(e.target.type) + (e.target.confidence ? ", " + esc(e.target.confidence) + " confidence" : "") +
    ", " + (cagr >= 0 ? "+" : "") + (cagr * 100).toFixed(1) + "% a year) · " + trkSources(e.sources) + "</p>" +
    '<div class="trk-event-input"><label for="ev-' + e.id + '">Your 2035 value (' + esc(e.unit) + ")</label>" +
    '<input type="range" id="ev-range-' + e.id + '" min="' + (e.target.value * 0.5) + '" max="' + (e.target.value * 1.5) + '" step="' + step + '" value="' + value + '" data-event="' + e.id + '" aria-label="' + esc(e.label) + ' 2035">' +
    '<input type="number" id="ev-' + e.id + '" min="0" step="' + step + '" value="' + (Math.round(value * 100) / 100) + '" data-event="' + e.id + '">' +
    '<output id="ev-out-' + e.id + '" class="trk-delta ' + (pct > 0.5 ? "up" : pct < -0.5 ? "down" : "") + '">' + trkPctText(pct) + " vs tracker" + (Math.abs(pct) > TRK_FULL_RANGE_PCT ? " (model effect capped at ±" + TRK_FULL_RANGE_PCT + "%)" : "") + "</output></div>" +
    (linked ? '<ul class="trk-linked">' + linked + "</ul>" : "") +
    (e.target.note ? '<p class="trk-note">' + esc(e.target.note) + "</p>" : "") + "</article>"
}

function trkApplications(sector) {
  if (!trkReady() || !sector) return ""
  var apps = TRACKER.applications.filter(function (a) { return a.industry === sector })
  if (!apps.length) return ""
  var byMetal = {}
  apps.forEach(function (a) { (byMetal[a.material] = byMetal[a.material] || []).push(a) })
  return '<details class="trk-apps"><summary>Products in this industry (' + apps.length + " tracker rows)</summary>" +
    '<table class="ev-table"><thead><tr><th>Material</th><th>Product form</th><th>Use</th><th>Status</th><th>Source</th></tr></thead><tbody>' +
    Object.keys(byMetal).map(function (m) {
      return byMetal[m].map(function (a, i) {
        return "<tr><td>" + (i === 0 ? "<b>" + esc(m) + "</b>" : "") + "</td><td>" + esc(a.form) + "</td><td>" + esc(a.use) + "</td><td>" + esc(a.status) + "</td><td>" + esc(a.source) + "</td></tr>"
      }).join("")
    }).join("") + "</tbody></table></details>"
}

function trkEventPanel(params) {
  if (!trkReady()) return '<p class="trk-note">Tracker data did not load.</p>'
  var sector = trkEventIndustry(params)
  var sectors = Object.keys(TRACKER.sectors)
  var counts = {}
  trkEvents().forEach(function (e) { counts[e.sector] = (counts[e.sector] || 0) + 1 })
  var select = '<div class="scn-filter-select"><label for="scn-ev-industry">Industry</label><select id="scn-ev-industry" name="scn-ev-industry" data-control>' +
    '<option value="">Choose an industry</option>' + sectors.map(function (s) {
      return '<option value="' + esc(s) + '"' + (s === sector ? " selected" : "") + ">" + esc(s) + " (" + (counts[s] || 0) + " events)</option>"
    }).join("") + "</select></div>"
  var active = trkActiveEvents(params)
  var activeLine = active.length ? '<p class="trk-active">Active events: ' + active.map(function (e) {
    return "<b>" + esc(e.label) + "</b> " + trkPctText(trkEventPct(params, e))
  }).join(" · ") + "</p>" : ""
  var body = ""
  if (sector) {
    var events = trkEvents(sector)
    body = events.length ? events.map(function (e) { return trkEventCard(params, e) }).join("") :
      '<p class="trk-note">The tracker has no series with both an actual value and a 2035 value for ' + esc(sector) +
      '. Add one to the <b>Database</b> tab (Metric “Sector activity”, Year 2035, Value, Unit, Source ID) and it appears here after the next data refresh.</p>'
    body += trkApplications(sector)
  }
  return '<fieldset class="scn-advanced-group trk-events"><legend>2035 events from the tracker</legend>' +
    '<p class="trk-note">Pick an industry, then replace a tracker 2035 value with your own. ±' + TRK_FULL_RANGE_PCT +
    "% against the tracker value moves that industry by the full model range.</p>" + select + activeLine + body + "</fieldset>"
}

/* ---------- Metal baselines ---------- */

function trkMetalBaseline(metal) {
  if (!trkReady()) return null
  var total = TRACKER.outlook.totals.find(function (t) { return t.metal === metal && t.y2035 })
  if (total) return { text: "2035 demand " + trkFmt(total.y2035, total.unit), value: total.y2035, unit: total.unit, source: total.source, label: total.label, basis: total.basis }
  var prod = TRACKER.production.find(function (p) { return p.metal === metal && p.country === "World" && p.y2025 })
  if (prod) return { text: "No 2035 baseline · 2025 world: " + prod.measure + " " + trkFmt(prod.y2025, "t"), value: null, source: prod.source, label: prod.label }
  return { text: "Not in the tracker yet", value: null }
}

/* ---------- Snapshot line ---------- */

function trkSnapshotLine() {
  if (!trkReady()) return ""
  return '<p class="trk-note">Data: <a href="' + esc(TRACKER.sheet) + '" target="_blank" rel="noopener">Sector Research Tracker</a>, snapshot ' + esc(TRACKER.snapshot) +
    " · " + TRACKER.events.length + " events, " + Object.keys(TRACKER.sources).length + " logged sources.</p>"
}

/* ---------- Supply, price and signposts for the decision brief ---------- */

var TRK_METAL_SIGNPOSTS = {
  Cobalt: "C1", Tungsten: "C2", Nickel: "C3", Manganese: "A2", Copper: "D6", Titanium: "C4", Aluminium: "B1", Chromium: "A3", Molybdenum: "A3", Zirconium: "A3"
}

function trkSupply(metal) {
  if (!trkReady()) return null
  var rows = TRACKER.production.filter(function (r) { return r.metal === metal })
  if (!rows.length) return null
  var measure = rows[0].measure
  var list = rows.filter(function (r) { return r.measure === measure && r.country !== "World" && r.share != null }).sort(function (a, b) { return b.share - a.share })
  if (!list.length) return null
  var hhi = Math.round(list.reduce(function (s, r) { return s + Math.pow(r.share * 100, 2) }, 0))
  return { measure: measure, top: list[0], top3: list.slice(0, 3), hhi: hhi, source: rows[0].source, label: rows[0].label }
}

function trkPrice(metal) {
  if (!trkReady() || !TRACKER.supplement) return null
  return TRACKER.supplement.find(function (r) { return r.metal === metal && /^Price/.test(r.indicator) && r.v0 && r.v1 }) || null
}

/* ---------- What each slider changes ---------- */

function trkSliderFeeds(industryKey) {
  return SCN_METAL_SHARES.filter(function (m) { return m.s[industryKey] }).map(function (m) {
    return { metal: m.metal, share: m.s[industryKey][0] / 100, flag: m.s[industryKey][1] }
  }).sort(function (a, b) { return b.share - a.share })
}

function trkSliderHelp(key) {
  var feeds = trkSliderFeeds(key)
  var events = trkEvents().filter(function (e) { return e.key === key })
  return (feeds.length ? "Share of each metal’s use in this industry: " + feeds.map(function (x) { return esc(x.metal) + " " + Math.round(x.share * 100) + "%" + (x.flag === "e" ? "*" : "") }).join(", ") +
    ". So +10% here moves " + esc(feeds[0].metal) + " demand by about +" + (Math.round(feeds[0].share * 100) / 10) + "%." : "No metal in the outlook has a share in this industry.") +
    (events.length ? " Tracker basis: " + esc(events[0].label) + " " + trkSources(events[0].sources) + "." : "")
}
